from pathlib import Path
import os, subprocess, tempfile, json, difflib, hashlib
root = Path.cwd()
art = root / '.session/artifacts'
art.mkdir(parents=True, exist_ok=True)
p = root / 'policy/proposals/store-readiness.yml'
lines = p.read_text().splitlines()
start = lines.index('        run: |') + 1
end = next(i for i in range(start, len(lines)) if lines[i].startswith('      - uses:'))
script = '\n'.join(s[10:] for s in lines[start:end]) + '\n'
(art / 'proposal.sh').write_text(script)
(art / 'proposal.diff').write_text(''.join(difflib.unified_diff((root / '.github/workflows/store-readiness.yml').read_text().splitlines(True), p.read_text().splitlines(True), fromfile='current', tofile='proposal')))
results = {'proposal_sha256': hashlib.sha256(p.read_bytes()).hexdigest(), 'syntax': subprocess.run(['bash', '-n'], input=script, text=True, capture_output=True).__dict__.get('returncode')}
with tempfile.TemporaryDirectory() as td:
    d = Path(td)
    env = dict(os.environ, GIT_CONFIG_GLOBAL=str(d/'config'), GIT_CONFIG_NOSYSTEM='1', GITHUB_RUN_ID='123', GIT_AUTHOR_NAME='review', GIT_AUTHOR_EMAIL='review@example.invalid', GIT_COMMITTER_NAME='review', GIT_COMMITTER_EMAIL='review@example.invalid')
    helpers = script[script.index('q()'):script.index('url()')]
    helper_test = '''mkdir -p work
''' + helpers + '''
git init -q --bare remote.git
git clone -q remote.git repo 2>/dev/null
printf 'seed\n' > repo/seed
git -C repo add seed
git -C repo commit -qm seed
printf 'mk_success=%s\n' "$(q mk repo probe)"
printf 'push_success=%s\n' "$(qp git -C repo push -q origin probe)"
printf 'mk_duplicate=%s\n' "$(q mk repo probe)"
printf 'q_failure=%s\n' "$(q bash -c 'exit 7')"
printf 'push_non_auth=%s\n' "$(qp git -C repo push -q missing probe)"
printf 'simulated_denial=%s\n' "$(qp bash -c 'echo "remote: Write access to repository not granted." >&2; exit 128')"
printf 'local_permission=%s\n' "$(qp bash -c 'echo "fatal: cannot open local file: Permission denied" >&2; exit 128')"
printf '%s\n' 'fatal: denied https://x:FAKE_TOKEN@host.invalid/store.git and '\''quoted/address'\'' unquoted-owner/private FAKE_TOKEN FAKE_MARKER FAKE_CONTENT' > work/err
printf 'first_redaction=%s\n' "$(first)"
'''
    r = subprocess.run(['bash'], input=helper_test, cwd=d, env=env, text=True, capture_output=True)
    results['helpers'] = {'exit':r.returncode, 'stdout':r.stdout, 'stderr':r.stderr}
    bindir=d/'bin'; bindir.mkdir()
    fake = '''#!/usr/bin/python3
import os,sys,pathlib,json
cmd=pathlib.Path(sys.argv[0]).name; a=sys.argv[1:]; mode=os.environ['CASE']
def emit(s): print(s)
def quit(n): sys.exit(n)
if cmd=='git':
 if a[0]=='config': quit(0)
 if a[0]=='clone':
  p=pathlib.Path(a[-1]); (p/'sentinels').mkdir(parents=True,exist_ok=True); (p/'sentinels/SENTINEL.txt').write_text('FAKE_MARKER'); quit(0)
 if 'grep' in a or 'log' in a:
  if mode=='git_search_failure': quit(128)
  if mode=='leak_hit': emit('matched-path')
  quit(0)
 if 'ls-remote' in a: quit(128)
 if 'push' in a:
  if 'work/scor' in a: print('remote: Write access to repository not granted.',file=sys.stderr); quit(128)
  quit(0)
 quit(0)
if cmd=='gh':
 if a[:2]==['run','list']:
  if mode=='run_list_failure': quit(1)
  if mode!='empty_runs': emit('101' if 'session.yml' in a else '102')
  quit(0)
 if a[:2]==['run','download']:
  if mode=='download_failure': quit(1)
  p=pathlib.Path(a[a.index('-D')+1]); (p/'payload.txt').write_text('ordinary')
  if mode=='tar_failure': (p/'payload.tar.gz').write_text('not a tar')
  quit(0)
 if a[0]=='api':
  endpoint=a[1]
  if '/issues' in endpoint:
   if mode=='api_failure': quit(1)
   emit('[]'); quit(0)
  if endpoint.endswith('/artifacts'):
   if mode=='artifact_api_failure': quit(1)
   emit('1'); quit(0)
  if endpoint.endswith('/logs'):
   if mode=='logs_failure': quit(1)
   emit('fake zip'); quit(0)
 quit(2)
if cmd=='unzip':
 p=pathlib.Path(a[a.index('-d')+1])
 if mode!='zero_log_files': (p/'job.txt').write_text('ordinary')
 quit(0)
if cmd=='grep':
 if mode=='positive_control_failure' and any('work/pc/' in x for x in a): quit(2)
 if mode=='actual_search_failure' and any('work/runs/' in x for x in a): quit(2)
 os.execv('/usr/bin/grep',['grep']+a)
'''
    for name in ['git','gh','unzip','grep']:
        f=bindir/name; f.write_text(fake); f.chmod(0o755)
    results['failure_matrix'] = []
    modes=['baseline','api_failure','run_list_failure','empty_runs','zero_log_files','logs_failure','artifact_api_failure','download_failure','tar_failure','positive_control_failure','git_search_failure','actual_search_failure','leak_hit']
    for errexit in [False, True]:
        for mode in modes:
            case=d/(mode+str(errexit)); case.mkdir()
            e=dict(env,PATH=str(bindir)+':'+os.environ['PATH'],CASE=mode,PHASE='initial',CUSTODIAN='FAKE_CUSTODIAN',SCORER='FAKE_SCORER',STORE='fake-owner/fake-private',PUBLIC='fake-owner/public')
            r=subprocess.run(['bash']+(['-e'] if errexit else []),input=script,cwd=case,env=e,text=True,capture_output=True)
            records=[]
            f=case/'out/steps.jsonl'
            if f.exists():
                try: records=[json.loads(x) for x in f.read_text().splitlines() if x.strip()]
                except Exception: pass
            results['failure_matrix'].append({'mode':mode,'bash_e':errexit,'exit':r.returncode,'d_records':[x for x in records if x['step']=='d'],'work_deleted':not (case/'work').exists(),'stderr':r.stderr})
(art/'checks.json').write_text(json.dumps(results,indent=2)+'\n')
print(json.dumps(results,indent=2))

